package com.logatron.tracequery.infrastructure;
import com.fasterxml.jackson.databind.*;import com.logatron.common.error.ApiException;import com.logatron.tracequery.configuration.TraceQueryProperties;import org.springframework.stereotype.Component;import java.io.IOException;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.util.Locale;
@Component public class TempoClient{
 private final TraceQueryProperties properties;private final ObjectMapper mapper;private final HttpClient client;
 public TempoClient(TraceQueryProperties properties,ObjectMapper mapper){this.properties=properties;this.mapper=mapper;this.client=HttpClient.newBuilder().connectTimeout(properties.timeout()).build();}
 public JsonNode trace(String traceId){try{String base=properties.tempoUrl().endsWith("/")?properties.tempoUrl().substring(0,properties.tempoUrl().length()-1):properties.tempoUrl();HttpRequest request=HttpRequest.newBuilder(URI.create(base+"/api/traces/"+URLEncoder.encode(traceId,StandardCharsets.UTF_8))).timeout(properties.timeout()).header("Accept","application/json").GET().build();HttpResponse<String> response=client.send(request,HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));if(response.statusCode()==404)throw ApiException.notFound();if(response.statusCode()==408||response.statusCode()==504)throw ApiException.timeout();if(response.statusCode()<200||response.statusCode()>=300){if(response.body().toLowerCase(Locale.ROOT).contains("timeout"))throw ApiException.timeout();throw ApiException.unavailable("Tempo");}return mapper.readTree(response.body());}catch(HttpTimeoutException ex){throw ApiException.timeout();}catch(InterruptedException ex){Thread.currentThread().interrupt();throw ApiException.unavailable("Tempo");}catch(IOException|IllegalArgumentException ex){throw ApiException.unavailable("Tempo");}}
}
